    /* sdd-asis-lifecycle:begin fnSearchInit — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('ipt_beginIndex').setValue("");
    clearBtnImage();
    await scwin.fnSearch();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearch
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSearch = async function () {
    /* sdd-asis-lifecycle:begin fnSearch — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const corpNm = $("#searchForm").find("input:text[name=searchCorpName]");
    corpNm.val(corpNm.val().trim());
    $c.util.getComponent("dma_fnDownloadReq").set("method", "searchCorp");
    $c.util.getComponent("dma_fnDownloadReq").set("forward", "searchCorp");
    await scwin.tx_fnSearch_ajaxsubmit();
    /* sdd-asis-lifecycle:end */
};


